insert into public.profession_cards (id, profession_id, module_id, position, kind, difficulty, checkpoint, title, body, answer, accepted_answers, answer_display, search_query, refs, tags, as_of, retired)
select id, profession_id, module_id, position, kind, difficulty, checkpoint, title, body, answer, accepted_answers, answer_display, search_query, refs, tags, as_of, retired from profession_card_rows_8c0a29472f
on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, kind = excluded.kind,
  difficulty = excluded.difficulty, checkpoint = excluded.checkpoint, title = excluded.title, body = excluded.body,
  answer = excluded.answer, accepted_answers = excluded.accepted_answers, answer_display = excluded.answer_display,
  search_query = excluded.search_query, refs = excluded.refs, tags = excluded.tags, as_of = excluded.as_of,
  retired = excluded.retired;

-- Cards of these modules that are no longer in the content are retired, never deleted.
update public.profession_cards set retired = true
 where module_id in ('mathematics/proofs-logic-sets', 'mathematics/calculus-1', 'mathematics/calculus-2', 'mathematics/linear-algebra-1', 'mathematics/multivariable-calculus', 'mathematics/discrete-math', 'mathematics/differential-equations-1')
   and not retired
   and id not in (select id from profession_card_rows_8c0a29472f);
drop table profession_card_rows_8c0a29472f;
